-- Description: Restore 4 official origins and coherent road geometries for Rota do Pedral to Balneário Luiz do Pedral.

BEGIN;

-- 1. Ensure 4 official origins exist with canonical coordinates and sort orders
INSERT INTO app_private.route_origins (
    id,
    route_id,
    code,
    name,
    location,
    sort_order,
    created_at,
    updated_at
) VALUES (
    'a17a314a-0000-4000-8000-000000000014',
    'a17a314a-0000-4000-8000-000000000002',
    'centro',
    'Centro (Praça da Matriz)',
    extensions.ST_SetSRID(extensions.ST_MakePoint(-52.206082, -3.205289), 4326)::extensions.geography,
    4,
    clock_timestamp(),
    clock_timestamp()
) ON CONFLICT (route_id, code) DO UPDATE SET
    name = EXCLUDED.name,
    location = EXCLUDED.location,
    sort_order = EXCLUDED.sort_order,
    updated_at = clock_timestamp();

UPDATE app_private.route_origins
SET location = extensions.ST_SetSRID(
        extensions.ST_MakePoint(
            CASE code
                WHEN 'rodoviaria' THEN -52.2198928
                WHEN 'aeroporto' THEN -52.2480994
                WHEN 'terminal_fluvial' THEN -52.2054132
            END,
            CASE code
                WHEN 'rodoviaria' THEN -3.2057320
                WHEN 'aeroporto' THEN -3.2534371
                WHEN 'terminal_fluvial' THEN -3.2058603
            END
        ),
        4326
    )::extensions.geography,
    sort_order = CASE code
        WHEN 'rodoviaria' THEN 1
        WHEN 'aeroporto' THEN 2
        WHEN 'terminal_fluvial' THEN 3
    END,
    updated_at = clock_timestamp()
WHERE route_id = 'a17a314a-0000-4000-8000-000000000002'
  AND code IN ('rodoviaria', 'aeroporto', 'terminal_fluvial');

