    bounds = EXCLUDED.bounds,
    source_hash = EXCLUDED.source_hash,
    updated_at = clock_timestamp();

-- 3. Recalculate route_actors corridor distance and origin_flags for 1km buffer
WITH corridor_calc AS (
    SELECT
        a.id AS actor_id,
        MIN(extensions.ST_Distance(a.location, rg.geometry))::integer AS min_dist,
        jsonb_build_object(
            'rodoviaria', bool_or(ro.code = 'rodoviaria' AND extensions.ST_DWithin(a.location, rg.geometry, 1000.0)),
            'aeroporto', bool_or(ro.code = 'aeroporto' AND extensions.ST_DWithin(a.location, rg.geometry, 1000.0)),
            'terminal_fluvial', bool_or(ro.code = 'terminal_fluvial' AND extensions.ST_DWithin(a.location, rg.geometry, 1000.0)),
            'centro', bool_or(ro.code = 'centro' AND extensions.ST_DWithin(a.location, rg.geometry, 1000.0))
        ) AS flags
    FROM app_private.actors a
    CROSS JOIN app_private.route_origins ro
    JOIN app_private.route_geometries rg ON rg.route_origin_id = ro.id
    WHERE ro.route_id = 'a17a314a-0000-4000-8000-000000000002'
      AND a.region_id = 'a17a314a-0000-4000-8000-000000000001'
      AND a.location IS NOT NULL
      AND a.deleted_at IS NULL
    GROUP BY a.id
    HAVING bool_or(extensions.ST_DWithin(a.location, rg.geometry, 1000.0)) = true
)
INSERT INTO app_private.route_actors (
    id,
    route_id,
    actor_id,
    distance_to_route_m,
    route_segment_index,
    origin_flags,
    created_at,
    updated_at
)
SELECT
    gen_random_uuid(),
    'a17a314a-0000-4000-8000-000000000002',
    c.actor_id,
    c.min_dist,
    0,
    c.flags,
    clock_timestamp(),
    clock_timestamp()
FROM corridor_calc c
ON CONFLICT (route_id, actor_id) DO UPDATE SET
    distance_to_route_m = EXCLUDED.distance_to_route_m,
    origin_flags = EXCLUDED.origin_flags,
    archived_at = NULL,
    updated_at = clock_timestamp();

-- Archive actors that are no longer within 1000m of any of the four geometries
UPDATE app_private.route_actors ra
SET archived_at = clock_timestamp(),
    updated_at = clock_timestamp()
WHERE ra.route_id = 'a17a314a-0000-4000-8000-000000000002'
  AND ra.archived_at IS NULL
  AND NOT EXISTS (
      SELECT 1
      FROM app_private.actors a
      CROSS JOIN app_private.route_origins ro
      JOIN app_private.route_geometries rg ON rg.route_origin_id = ro.id
      WHERE a.id = ra.actor_id
        AND ro.route_id = 'a17a314a-0000-4000-8000-000000000002'
        AND extensions.ST_DWithin(a.location, rg.geometry, 1000.0)
  );

COMMIT;
